   "id": "ze06aff7b",
   "sez": "italia",
   "titolo": "Tensioni all'ex Ghetto ebraico di Roma, insulti e urla contro l'Anpi",
   "orig": "Tensioni all'ex Ghetto ebraico a Roma, insulti e urla contro l'Anpi",
   "lead": "Nell'ex Ghetto ebraico di Roma si sono verificate tensioni durante una commemorazione legata al rastrellamento nazista, con insulti e urla contro i rappresentanti dell'Anpi. Il presidente dell'associazione provinciale ha denunciato di essere stato attaccato e di non essere stato voluto in quella piazza. Nei giorni precedenti era arrivata una richiesta di non partecipare alla cerimonia, con l'accusa all'associazione di essere \"pro Pal\" e quindi non legittimata a presenziare. L'episodio mette in luce le tensioni legate al conflitto in Medio Oriente anche nelle commemorazioni della memoria storica italiana.",
   "more": [
    "L'Anpi (Associazione Nazionale Partigiani d'Italia) è l'organizzazione che riunisce chi ha combattuto nella Resistenza e i loro eredi morali, impegnata nella difesa dei valori antifascisti e nella memoria storica, spesso presente alle commemorazioni pubbliche legate alla Seconda guerra mondiale e alla Shoah."
   ],
