   "sez": "mondo",
   "titolo": "Attacco russo con drone ferisce 7 persone a Rivne, in Ucraina",
   "orig": "Russian drone attack injures 7 in Ukraine’s Rivne",
   "lead": "Droni russi hanno colpito nella notte tra il 15 e il 16 ottobre la città di Rivne, nell'Ucraina occidentale, ferendo sette persone. L'attacco si inserisce nella campagna di bombardamenti russi contro il territorio ucraino. Nello stesso contesto, quattro droni russi hanno violato lo spazio aereo della Moldova durante un attacco notturno contro l'Ucraina, episodio che sottolinea i crescenti rischi per la sicurezza della Moldova e della regione legati alla guerra russa contro il vicino ucraino.",
   "more": [
    "Rivne è una città dell'Ucraina occidentale, lontana dalla linea del fronte ma comunque colpita periodicamente da attacchi russi con missili e drone, parte della strategia di Mosca per colpire infrastrutture e indebolire il morale della popolazione civile ucraina."
   ],
