   "titolo": "Il presidente del Ghana Mahama ribadisce l'impegno per investimenti privati e crescita industriale",
   "orig": "Mahama reaffirms commitment to private investment and industrial growth",
   "lead": "Il presidente del Ghana John Dramani Mahama ha ribadito l'impegno del governo a creare un ambiente favorevole per gli investimenti privati e la crescita industriale nel paese. Lo riferisce MyJoyOnline.",
