   "lead": "È stato rivelato il cast principale dell'adattamento anime televisivo di 'Kizuguchi to Houtai' (Wound & Bandage), manga di Nanai Umihoshi, con Hisako Kanemoto e Chikahiro Kobayashi tra le voci protagoniste. La serie, diretta da Miyuki Ishida presso lo studio J.C.Staff, debutterà il 9 gennaio alle 23:00 su AT-X, per poi essere trasmessa anche su ABC TV e TV Asahi nel blocco di programmazione ANiMAZiNG.",
