   "orig": "Meeting highlights from the Committee for Medicinal Products for Human Use (CHMP) 12-15 October 2026",
   "lead": "Il Comitato per i medicinali per uso umano (CHMP) dell'Agenzia europea per i medicinali ha raccomandato l'approvazione di sei nuovi farmaci nella riunione di ottobre 2026. Tra questi figurano Foundayo (orforglipron), richiesto da Eli Lilly Nederland, e Rasonque (daraxonrasib), presentato da Revolution Medicines Netherlands per il trattamento del cancro al pancreas metastatico. Lo riferisce l'Agenzia europea per i medicinali (Ema).",
