   "orig": "Four key tourism projects to be rolled out",
   "lead": "Il governo di Hong Kong avvierà, a partire dal quarto trimestre dell'anno, nuovi progetti turistici che comprendono tour di marchi industriali, un'esposizione dedicata a una città in miniatura e percorsi immersivi nella cultura dei templi. Lo ha annunciato il gruppo di lavoro per lo sviluppo di nuovi punti d'interesse turistico, guidato dal vicesegretario capo Warner Cheuk, secondo cui i nove progetti già lanciati nella prima fase hanno riscosso buon successo. Lo riferisce RTHK.",
