   "titolo": "La Cina chiede a Israele di fermare gli insediamenti in Cisgiordania",
   "orig": "China tells Israel to stop 'forced establishment' of West Bank settlements",
   "lead": "Il ministro degli Esteri cinese Wang Yi ha invitato Israele a interrompere quella che ha definito la 'imposizione forzata' di nuovi insediamenti in Cisgiordania, durante un colloquio con il presidente israeliano Isaac Herzog a margine di una conferenza. Wang ha definito la questione palestinese 'la più grande ingiustizia storica di questo secolo'. L'incontro si è svolto in un contesto internazionale di crescente attenzione verso la crisi israelo-palestinese e il ruolo diplomatico della Cina nella regione.",
   "more": [
    "La Cisgiordania è il territorio palestinese occupato da Israele dal 1967, dove da decenni vengono costruiti insediamenti israeliani considerati illegali dalla maggior parte della comunità internazionale. La questione degli insediamenti resta uno dei principali ostacoli a qualsiasi processo di pace tra israeliani e palestinesi."
   ],
