   "titolo": "OpenAI promette 5 milioni di dollari a una fondazione matematica dopo le proteste dei matematici",
   "orig": "OpenAI tries to solve mathematician backlash problem by pledging $5 million to math foundation",
   "lead": "OpenAI ha annunciato una donazione di 5 milioni di dollari a una fondazione dedicata alla matematica, in risposta alle critiche sollevate dalla comunità scientifica dopo la pubblicazione di centinaia di articoli generati con intelligenza artificiale. L'Association for Human Mathematics ha dichiarato che 'i matematici non hanno chiesto che questo lavoro venisse fatto', sottolineando il malcontento per l'uso massiccio di strumenti AI nel settore. La vicenda si inserisce in un dibattito più ampio sull'impatto dell'intelligenza artificiale generativa sulla ricerca scientifica.",
   "more": [
    "OpenAI è l'azienda statunitense che sviluppa modelli di intelligenza artificiale come ChatGPT, oggi utilizzati anche per generare contenuti scientifici e articoli accademici, sollevando dubbi tra i ricercatori sulla qualità e l'autenticità di tali produzioni."
   ],
