   "titolo": "A Chennai un centro comunitario con tetto a volta a botte firmato Spaces by Manah",
   "orig": "Spaces by Manah signposts Chennai community centre with barrel-vaulted roof",
   "lead": "Lo studio di architettura indiano Spaces by Manah ha completato a Chennai, in India, il centro comunitario 'The Soil & Sea', caratterizzato da un tetto a volta a botte in mattoni che funge da elemento distintivo e riconoscibile del sito. L'edificio, esteso su 4.330 metri quadrati, è stato progettato per offrire spazi didattici a un centro educativo locale e per ospitare laboratori ed eventi comunitari. Lo riferisce Dezeen.",
   "more": [
    "La volta a botte è un elemento architettonico curvo tradizionalmente realizzato in mattoni o pietra, usato per coprire grandi spazi senza bisogno di colonne interne, spesso impiegato in India per le sue proprietà di ventilazione naturale e resistenza al clima caldo."
   ],
