   "sez": "organizzazioni",
   "titolo": "L'AIEA aiuta i Paesi a mobilitare investimenti per ampliare i servizi di radioterapia",
   "orig": "IAEA Helps Countries Mobilize Investment to Expand Radiotherapy Services",
   "lead": "L'Agenzia internazionale per l'energia atomica ha annunciato il proprio supporto a diversi Paesi per mobilitare investimenti destinati all'ampliamento dei servizi di radioterapia, una terapia fondamentale per la cura dei tumori. L'iniziativa punta a colmare le disparità nell'accesso a trattamenti oncologici avanzati nelle aree con risorse limitate. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "La radioterapia è una terapia oncologica che utilizza radiazioni ionizzanti per distruggere le cellule tumorali; l'accesso a queste tecnologie resta molto diseguale nel mondo, soprattutto nei Paesi a basso e medio reddito."
   ],
