   "lead": "La Casa dei Cavalieri di Rodi a Roma, resa celebre anche dal film 'Il Marchese del Grillo', viene presentata come uno dei punti panoramici più suggestivi della capitale, da cui si gode una vista che sembra permettere di 'toccare' la città con un dito. L'articolo ripercorre il fascino del luogo dai tempi antichi fino a oggi. Lo riferisce Turisti per Caso.",
