   "orig": "‘We’re potty for vintage Polo Ralph Lauren’",
   "lead": "Il marchio Polo Ralph Lauren vintage, simbolo dello stile preppy, sta per ottenere un proprio festival dedicato, segno della crescente passione di collezionisti e appassionati per i capi d'archivio del brand. L'articolo del Financial Times si interroga su cosa renda così popolare questo stile di abbigliamento d'epoca tra un pubblico sempre più ampio. Lo riferisce Financial Times.",
