 "confronti": {
  "z1838bc4e": {
   "voci": [
    {
     "n": "Al Jazeera",
     "c": "Doha",
     "p": "QA",
     "t": "Riporta solo titolo e occhiello: Infantino avrebbe parlato alla riunione del board Fifa a Zurigo tra richieste di dimissioni. Giudizio parziale per assenza del testo completo.",
     "b": "t"
    },
    {
     "n": "The Guardian",
     "c": "Londra",
     "p": "UK",
     "t": "Si concentra sul premio per la pace Fifa assegnato a Trump, riportando che membri del consiglio hanno chiesto di abolirlo o 'depoliticizzarlo' dopo le polemiche. Cita un comitato interno che deciderà prima della riunione di Doha del 16 dicembre, e un membro anonimo del consiglio come fonte.",
     "b": "a"
    },
    {
     "n": "PBS NewsHour",
     "c": "Arlington",
     "p": "US",
     "t": "Racconta le scuse di Infantino per gli 'errori' nel piano di investimento da 4,2 miliardi di dollari con Kushner, poi abbandonato, e la delusione dei delegati europei che parlano di 'nessuna risposta satisfacente'. Cita Neuendorf e Debbie Hewitt come critici, e il membro africano Ahmed Yahya come sostenitore di Infantino.",
     "b": "a"
    },
    {
     "n": "Hespress English",
     "c": "Rabat",
     "p": "XX",
     "t": "Riporta le stesse dichiarazioni di Neuendorf ('nessuna risposta satisfacente') e Hewitt sulle scuse 'con contrizione', incentrandosi sul fallito progetto FFE e sul nuovo fondo di sviluppo da 6,35 miliardi di dollari. Menziona anche il caso Balogun e il premio per la pace a Trump come fattori di tensione.",
     "b": "a"
    },
    {
     "n": "Actu Cameroun",
     "c": "Yaoundé",
     "p": "XX",
     "t": "Riporta le scuse ufficiali di Infantino per gli 'errori di gestione e comunicazione' sul progetto FFE, citando le sue parole secondo cui si trattava solo di una 'proposta' e non di una 'decisione definitiva'. Dà rilievo al bilancio di Infantino e all'aumento dei fondi a 25 milioni di dollari per associazione membro.",
     "b": "a"
    }
   ],
   "divergono": "Il Guardian pone al centro la vicenda del premio per la pace a Trump e le pressioni per abolirlo, aspetto assente in Actu Cameroun che si concentra invece sul bilancio positivo di Infantino. PBS NewsHour e Hespress English condividono le stesse citazioni critiche di Neuendorf e Hewitt sull'assenza di risposte, mentre Actu Cameroun riporta solo le parole di scuse di Infantino senza le reazioni critiche europee. Le cifre differiscono: PBS parla di piano da 4,2 miliardi di dollari e fondo di sviluppo, Hespress cita 6,35 miliardi per il fondo sviluppo e 25 milioni per federazione, dato ripreso anche da Actu Cameroun."
  }
 },
